import { xalor } from '@bgskinner2/xalor';

// Assert Mode: Throws explicit diagnostic exceptions if data fails validation
const profile = xalor.assert<'USER'>(payload);

// Audit Mode: Non-throwing validation that returns a detailed ledger of all errors
const reportingLedger = xalor.audit<'USER'>(payload);

